/* HEXA BATTLEGROUNDS setup — PART 3 OF 19. Run parts in order. Safe to re-run. */ create or replace function _complete(p_instance uuid) returns int language plpgsql as $$ declare mi mission_instances; mt mission_templates; t teams; l locations; sr sync_rounds; v_ev uuid; v_pts int := 0; v_coins int := 0; v_item text; v_won boolean; ad airdrops; v_total numeric; v_left numeric; begin select * into mi from mission_instances where id = p_instance for update; if mi.status <> 'active' then return 0; end if; select * into mt from mission_templates where id = mi.template_id; select * into t from teams where id = mi.team_id; v_ev := t.event_id; update mission_instances set status = 'solved', solved_at = now() where id = mi.id; if mi.kind = 'battle' then perform 1 from battles where id = mi.battle_id for update; if exists (select 1 from battles where id = mi.battle_id and status = 'active') then perform _resolve_battle(mi.battle_id, mi.team_id); return _cfg(v_ev, 'pts_battle'); end if; update mission_instances set status = 'failed' where id = mi.id; return 0; elsif mi.kind = 'recovery' then perform _respawn(mi.team_id, 'solved'); return 0; elsif mi.sync_round_id is not null then select * into sr from sync_rounds where id = mi.sync_round_id; v_total := greatest(1, extract(epoch from sr.deadline - sr.started_at)); v_left := greatest(0, extract(epoch from sr.deadline - now())); v_pts := round(sr.max_points * (0.5 + 0.5 * v_left / v_total)); if mt.relay and mi.fallback_at is not null and now() >= mi.fallback_at then v_pts := v_pts / 2; end if; if mi.hint_used then v_pts := round(v_pts * 0.8); end if; perform _apply(mi.team_id, 'finale', v_pts, 0, 0, 0, mi.id::text, mt.title); update teams set final_points = final_points + v_pts where id = mi.team_id; elsif mi.kind = 'airdrop' then update airdrops set claimed_by = mi.team_id, claimed_at = now(), status = 'claimed' where id = mi.airdrop_id and claimed_by is null and status = 'open' returning * into ad; v_won := ad.id is not null; if v_won then v_pts := _cfg(v_ev, 'pts_airdrop'); v_coins := case ad.tier when 'common' then 40 when 'rare' then 60 when 'legendary' then 100 when 'mystery' then 20 + abs(hashtext(ad.id::text)) % 101 when 'cursed' then 0 else 30 end; if ad.tier = 'cursed' then v_pts := v_pts * 2; end if; if t.beacon then v_coins := v_coins * 2; update teams set beacon = false where id = t.id; end if; perform _apply(mi.team_id, 'airdrop', v_pts, v_coins, 0, 0, ad.id::text, ad.tier || ' airdrop'); if ad.tier = 'cursed' then perform _damage(mi.team_id, 20, 'curse', ad.id::text, 'Cursed airdrop'); end if; if ad.tier = 'intel' then update teams set scan_until = now() + interval '120 seconds' where id = t.id; end if; v_item := case ad.tier when 'legendary' then 'sniper' when 'rare' then 'shield' when 'common' then 'medkit' when 'mystery' then (array['smg', 'jammer', 'scanner', 'extract'])[1 + abs(hashtext(ad.id::text || 'i')) % 4] else null end; if v_item is not null then perform _add_item(mi.team_id, v_item, 1); end if; if ad.tier = 'legendary' then perform _add_item(mi.team_id, 'shield', 1); end if; perform _feed(t.arena_id, 'airdrop.claimed', jsonb_build_object('team', t.number, 'tier', ad.tier, 'location', ad.location_id)); update mission_instances set status = 'cancelled' where airdrop_id = mi.airdrop_id and status = 'active' and id <> mi.id; perform _ping_arena(t.arena_id, 'airdrop'); else perform _apply(mi.team_id, 'airdrop_consolation', 0, 15, 0, 0, mi.id::text, 'Airdrop already taken'); end if; else v_pts := coalesce(mt.points, case when mt.difficulty >= 2 then _cfg(v_ev, 'pts_hard') else _cfg(v_ev, 'pts_standard') end); v_coins := mt.coins; if mi.hint_used then v_pts := round(v_pts * 0.8); end if; if mt.relay then if mi.fallback_at is not null and now() >= mi.fallback_at then v_pts := v_pts / 2; elsif mi.partner_team_id is not null then perform _apply(mi.partner_team_id, 'relay_assist', _cfg(v_ev, 'pts_relay_bonus'), 0, 0, 10, mi.id::text, 'Shared a codeword'); perform _apply(mi.team_id, 'relay_trust', 0, 0, 0, 5, mi.id::text, 'Cooperated'); perform _feed(t.arena_id, 'intel.shared', jsonb_build_object('from', (select number from teams where id = mi.partner_team_id), 'to', t.number)); perform _ping_team(mi.partner_team_id, 'intel'); end if; end if; perform _apply(mi.team_id, 'mission', v_pts, v_coins, 0, 0, mi.id::text, mt.title); update teams set missions_completed = missions_completed + 1 where id = mi.team_id; select * into l from locations where id = mi.location_id; if l.id is not null and array_length(l.loot, 1) > 0 then v_item := l.loot[1 + abs(hashtext(mi.id::text)) % array_length(l.loot, 1)]; perform _add_item(mi.team_id, v_item, 1); end if; end if; update mission_instances set points_awarded = v_pts where id = mi.id; perform _feed(t.arena_id, 'mission.completed', jsonb_build_object('team', t.number, 'title', mt.title, 'points', v_pts, 'item', v_item)); perform _ping_team(mi.team_id, 'result'); perform _ping_arena(t.arena_id, 'score'); return v_pts; end $$; create or replace function _fail(p_instance uuid, p_status text default 'failed') returns void language plpgsql as $$ declare mi mission_instances; t teams; b battles; begin select * into mi from mission_instances where id = p_instance for update; if mi.status <> 'active' then return; end if; update mission_instances set status = p_status where id = mi.id; select * into t from teams where id = mi.team_id; if mi.kind = 'battle' then select * into b from battles where id = mi.battle_id; if not exists (select 1 from mission_instances where battle_id = mi.battle_id and status = 'active') then perform _resolve_battle(mi.battle_id, null); end if; elsif mi.kind = 'recovery' then perform _respawn(mi.team_id, 'bounded'); elsif mi.sync_round_id is null and mi.kind in ('mission', 'relay') then perform _damage(mi.team_id, _cfg(t.event_id, 'dmg_fail'), 'mission_fail', mi.id::text, 'Mission failed'); end if; perform _feed(t.arena_id, 'mission.failed', jsonb_build_object('team', t.number)); perform _ping_team(mi.team_id, 'result'); end $$; create or replace function _arrive(p_team uuid) returns void language plpgsql as $$ declare t teams; a arenas; v_from locations; v_to locations; v_count int; begin select * into t from teams where id = p_team for update; if t.state <> 'traveling' then return; end if; select * into a from arenas where id = t.arena_id; select * into v_from from locations where id = t.travel_from; select * into v_to from locations where id = t.travel_to; update teams set state = 'idle', location_id = travel_to, travel_to = null, travel_from = null, travel_arrive_at = null, travel_started_at = null, dropped = true, visit_missions = 0 where id = p_team; if a.zone_next_at is not null and v_from.collapse_stage = a.zone_stage + 1 and v_to.collapse_stage > a.zone_stage + 1 then perform _apply(p_team, 'relocation', _cfg(a.event_id, 'pts_relocation'), 0, 0, 0, 'reloc-' || (a.zone_stage + 1), 'Reached safety before the zone collapsed'); end if; if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.arrived', jsonb_build_object('team', t.number, 'location', v_to.id)); end if; select count(*) into v_count from teams where arena_id = t.arena_id and location_id = v_to.id and id <> t.id and ready; if v_count > 0 then perform _feed(t.arena_id, 'encounter.detected', jsonb_build_object('location', v_to.id, 'squads', v_count + 1)); perform _ping('arena-' || t.arena_id::text, 'encounter'); end if; if a.phase = 'play' and not exists (select 1 from mission_instances where team_id = p_team and status = 'active' and kind <> 'battle') then perform _start_location_mission(p_team); end if; perform _ping_team(p_team, 'arrived'); end $$; create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare a arenas; r record; v_changed boolean := false; v_sched text[]; v_next int; v_at timestamptz; begin if not pg_try_advisory_xact_lock(hashtext('tick' || p_arena::text)) then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or a.paused then return false; end if; if not p_force and a.last_tick_at is not null and a.last_tick_at > now() - interval '800 milliseconds' then return false; end if; update arenas set last_tick_at = now() where id = p_arena; if a.phase = 'shuttle' and now() >= a.shuttle_arrive_at then update arenas set phase = 'roles', roles_deadline = now() + _secs(_cfg(a.event_id, 'roles_seconds')) where id = p_arena; update teams set location_id = 'gate_1', state = 'idle' where arena_id = p_arena and ready; perform _feed(p_arena, 'shuttle.arrived', '{}'::jsonb); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'roles' and now() >= a.roles_deadline then perform _finalize_roles(p_arena); update arenas set phase = 'play', play_started_at = now() where id = p_arena; perform _feed(p_arena, 'role.assignment.completed', '{}'::jsonb); perform _feed(p_arena, 'map.revealed', '{}'::jsonb); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase not in ('play', 'finale') then if v_changed then perform _ping_arena(p_arena, 'phase'); end if; return v_changed; end if; for r in select id from teams where arena_id = p_arena and state = 'traveling' and travel_arrive_at <= now() loop perform _arrive(r.id); v_changed := true; end loop; for r in select id from battles where arena_id = p_arena and status = 'active' and deadline <= now() loop perform _resolve_battle(r.id, null); v_changed := true; end loop; for r in select id, kind, sync_round_id from mission_instances where arena_id = p_arena and status = 'active' and deadline <= now() and kind <> 'battle' loop perform _fail(r.id, 'expired'); v_changed := true; end loop; for r in select id from teams where arena_id = p_arena and state = 'recovery' and recovery_deadline <= now() loop perform _respawn(r.id, 'timeout'); v_changed := true; end loop; for r in select id from sync_rounds where arena_id = p_arena and status = 'active' and deadline <= now() loop update sync_rounds set status = 'closed' where id = r.id; update arenas set sync_round_id = null where id = p_arena and sync_round_id = r.id; perform _feed(p_arena, 'sync.closed', '{}'::jsonb); v_changed := true; end loop; select * into a from arenas where id = p_arena; if a.phase = 'play' and _cfg(a.event_id, 'zone_auto') = 1 and a.zone_next_at is null and a.zone_stage < 5 then v_sched := string_to_array(_cfg_text(a.event_id, 'zone_schedule'), ','); v_next := trim(v_sched[a.zone_stage + 1])::int; if v_next is not null then v_at := a.play_started_at + make_interval(mins => v_next); if now() >= v_at - _secs(_cfg(a.event_id, 'zone_warning')) then update arenas set zone_next_at = greatest(v_at, now() + interval '10 seconds') where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; end if; select * into a from arenas where id = p_arena; if a.zone_next_at is not null and now() >= a.zone_next_at then perform _zone_advance(p_arena); v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'airdrop_interval') > 0 and coalesce(a.last_airdrop_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'airdrop_interval')) then perform _spawn_airdrop(p_arena, null, (array['common', 'common', 'rare', 'mystery', 'intel', 'cursed', 'legendary'])[1 + floor(random() * 7)::int]); v_changed := true; end if; update airdrops set status = 'expired' where arena_id = p_arena and status = 'open' and expires_at <= now(); if found then v_changed := true; end if; update mission_instances mi set status = 'cancelled' from airdrops ad where mi.airdrop_id = ad.id and ad.status = 'expired' and mi.status = 'active'; update alliances set status = 'expired' where arena_id = p_arena and status = 'proposed' and created_at < now() - interval '2 minutes'; update alliances set status = 'ended' where arena_id = p_arena and status = 'active' and expires_at <= now(); if v_changed then perform _ping_arena(p_arena, 'tick'); end if; return v_changed; end $$; create or replace function _auth_player(p_token text) returns players language plpgsql as $$ declare p players; begin select * into p from players where session_hash = _hash(p_token) and active; if p.id is null then raise exception 'AUTH'; end if; if p.last_seen_at < now() - interval '8 seconds' then update players set last_seen_at = now() where id = p.id; end if; return p; end $$; create or replace function _auth_captain(p_token text) returns players language plpgsql as $$ declare p players; a arenas; begin p := _auth_player(p_token); if p.role is distinct from 'captain' then raise exception 'NOT_CAPTAIN'; end if; select ar.* into a from arenas ar join teams t on t.arena_id = ar.id where t.id = p.team_id; if a.phase not in ('play', 'finale') then raise exception 'NOT_IN_PLAY'; end if; if a.paused then raise exception 'PAUSED'; end if; perform _tick(a.id); return p; end $$; create or replace function map_data() returns jsonb language sql stable security definer set search_path = public as $$ select jsonb_build_object( 'locations', (select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'building', building, 'floor', floor, 'x', x, 'y', y, 'kind', kind, 'collapse', collapse_stage, 'risk', risk, 'reward', reward, 'tags', tags, 'drop', drop_zone, 'enabled', enabled) order by id) from locations), 'edges', (select jsonb_agg(jsonb_build_array(a, b, seconds)) from edges), 'items', (select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'kind', kind, 'description', description, 'price', price, 'params', params) order by price) from items) ) $$; create or replace function join_team( p_event_code text, p_team_number int, p_pin text, p_name text, p_consent boolean, p_rules boolean, p_existing_token text default null ) returns jsonb language plpgsql security definer set search_path = public as $$ declare e events; t teams; p players; v_token text; v_count int; v_fails int; begin select * into e from events where code = upper(trim(p_event_code)); if e.id is null then raise exception 'NO_EVENT'; end if; if p_existing_token is not null and length(p_existing_token) > 0 then select pl.* into p from players pl join teams tm on tm.id = pl.team_id where pl.session_hash = _hash(p_existing_token) and pl.active and tm.event_id = e.id; if p.id is not null then select * into t from teams where id = p.team_id; return jsonb_build_object('token', p_existing_token, 'team', t.number, 'rejoined', true); end if; end if; if not coalesce(p_consent, false) or not coalesce(p_rules, false) then raise exception 'CONSENT_REQUIRED'; end if; if p_name is null or char_length(trim(p_name)) < 1 or char_length(trim(p_name)) > 40 then raise exception 'BAD_NAME'; end if; select count(*) into v_fails from pin_failures where event_id = e.id and team_number = p_team_number and at > now() - interval '5 minutes'; if v_fails >= 8 then raise exception 'LOCKED_OUT'; end if; select * into t from teams where event_id = e.id and number = p_team_number for update; if t.id is null or t.pin_hash <> _hash(t.pin_salt || coalesce(p_pin, '')) then insert into pin_failures(event_id, team_number) values (e.id, p_team_number); return jsonb_build_object('error', 'BAD_PIN'); end if; if t.roster_locked then raise exception 'ROSTER_LOCKED'; end if; select count(*) into v_count from players where team_id = t.id and active; if v_count >= 4 then raise exception 'TEAM_FULL'; end if; if exists (select 1 from players where team_id = t.id and active and lower(display_name) = lower(trim(p_name))) then raise exception 'NAME_TAKEN'; end if; v_token := _new_token(); insert into players(team_id, display_name, session_hash, consent) values (t.id, trim(p_name), _hash(v_token), true) returning * into p; if v_count + 1 = 4 then update teams set ready = true, roster_locked = true where id = t.id; perform _feed(t.arena_id, 'team.ready', jsonb_build_object('team', t.number)); else perform _feed(t.arena_id, 'player.joined', jsonb_build_object('team', t.number, 'count', v_count + 1)); end if; perform _ping_team(t.id, 'roster'); perform _ping_arena(t.arena_id, 'roster'); return jsonb_build_object('token', v_token, 'team', t.number, 'rejoined', false); end $$; create or replace function claim_role(p_token text, p_role text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; a arenas; begin p := _auth_player(p_token); if p_role not in ('captain', 'scout', 'decoder', 'intel') then raise exception 'BAD_ROLE'; end if; select ar.* into a from arenas ar join teams t on t.arena_id = ar.id where t.id = p.team_id; perform _tick(a.id); select * into a from arenas where id = a.id; if a.phase <> 'roles' or now() >= a.roles_deadline then raise exception 'ROLES_CLOSED'; end if; if p.role is not null then raise exception 'ALREADY_HAS_ROLE'; end if; begin update players set role = p_role where id = p.id and role is null; exception when unique_violation then raise exception 'ROLE_TAKEN'; end; perform _ping_team(p.team_id, 'roles'); return jsonb_build_object('role', p_role); end $$;
